<span class="line"><span style="color:#ABB2BF;">    poly_features[:, i] </span><span style="color:#56B6C2;">/=</span><span style="color:#ABB2BF;"> math.</span><span style="color:#61AFEF;">gamma</span><span style="color:#ABB2BF;">(i </span><span style="color:#56B6C2;">+</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">)  </span><span style="color:#7F848E;font-style:italic;"># gamma(n)=(n-1)!</span></span>
